#!/usr/bin/env python3
"""Проверить политику временных сообщений, content receipts и секретное чтение."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import resource
import subprocess
import tempfile

from validate_quick_format import block

ROOT = Path(__file__).resolve().parents[1]
CORE = 'submodules/TelegramCore/Sources/'
POLICY = CORE + 'Utils/NagramiXCaptureProtectionPolicy.swift'
MARK = CORE + 'TelegramEngine/Messages/MarkMessageContentAsConsumedInteractively.swift'
SECRET = CORE + 'State/ManagedSecretChatOutgoingOperations.swift'
APPLY = CORE + 'TelegramEngine/Messages/ApplyMaxReadIndexInteractively.swift'
SYNC = CORE + 'State/SynchronizePeerReadState.swift'
ARCHIVE = CORE + 'Utils/NagramiXMessageArchive.swift'


def sha(data):
    return hashlib.sha256(data).hexdigest()


def verify(source, baseline, archive_source):
    for name, expected in BEFORE.items():
        assert sha((baseline / name).read_bytes()) == expected, 'Wrong pre-task source: ' + name
    assert json.loads((baseline / 'versions.json').read_text())['app'] == '13.2'
    texts = {name: (source / name).read_text() for name in BEFORE}
    plan_path = ROOT / 'ios/temporary_message_interaction_patches.json'
    if plan_path.exists():
        plan = json.loads(plan_path.read_text())
        for name in BEFORE:
            assert sha(texts[name].encode()) == plan['outputs'][name], 'Final output drift: ' + name
    archive = archive_source or source / ARCHIVE
    archive_text = archive.read_text()
    assert 'public func shouldSuppressTemporaryContentReceipt(id: MessageId) -> Bool' in archive_text
    assert 'public func shouldSuppressTemporaryContentReceipt(peerId: PeerId, globallyUniqueId: Int64) -> Bool' in archive_text
    assert 'public func temporaryInteractionMessage(id: MessageId, liveMessage: Message?) -> Message?' in archive_text
    policy = texts[POLICY]
    helper = block(policy, 'private func nagramiXCanRetainTemporaryMessage(id:')
    assert 'containsSecretMedia' not in helper and 'timeout <= 60' not in helper
    assert 'TelegramMediaAction' in helper and 'EphemeralMessageAttribute' in helper
    assert set(re.findall(r'bool\(forKey: "([^"]+)"\)', policy)) == {'nagramix.messages.saveTemporaryMessages', 'nagramix.messages.replayViewOnce'}
    assert block(texts[MARK], 'func markMessageContentAsConsumedRemotely(') == block((baseline / MARK).read_text(), 'func markMessageContentAsConsumedRemotely('), 'Do not rewrite server truth'
    assert block(texts[SECRET], 'private func boxedDecryptedSecretMessageAction(') == block((baseline / SECRET).read_text(), 'private func boxedDecryptedSecretMessageAction('), 'Native serializers unchanged'
    assert block(texts[SECRET], 'private func markOutgoingOperationAsCompleted(') == block((baseline / SECRET).read_text(), 'private func markOutgoingOperationAsCompleted('), 'Native sequence ACK unchanged'
    service = block(texts[SECRET], 'private func sendServiceActionMessage(')
    assert 'boxedDecryptedSecretMessageAction(action: effectiveAction)' in service
    assert 'globallyUniqueId: effectiveAction.globallyUniqueId' in service
    assert 'operationIndex: tagLocalIndex' in service and 'wasDelivered: wasDelivered' in service
    assert 'captureTemporaryBeforeViewing(message: sentMessage)' in texts[SECRET]
    # All cloud branches remain byte-identical after removing only the approved
    # secret-peer predicate. It is false for every ordinary cloud history.
    native_ghost = 'NagramiXGhostSettings.current.hidesMessageReads'
    new_ghost = '(NagramiXGhostSettings.current.hidesMessageReads || nagramiXShouldSuppressTemporarySecretHistory(peerId: peerId))'
    assert texts[SYNC].replace(new_ghost, native_ghost) == (baseline / SYNC).read_text()
    view = block(texts[CORE + 'State/AccountViewTracker.swift'], '    public func updateSeenLiveLocationForMessageIds(')
    assert view.count('id: allowedIds.map { $0.id }') == 2
    assert 'guard !allowedIds.isEmpty else { return .complete() }' in view
    assert 'updatedSeenLiveLocationMessageIdsAndTimestamps.removeValue(forKey: id)' in view
    personal = texts[CORE + 'State/ManagedConsumePersonalMessagesActions.swift']
    assert personal.count('if nagramiXShouldSuppressTemporaryReceipt(transaction: transaction, postbox: postbox, messageId: id)') == 2
    return texts, archive


